// Aurora Mail mini app HTML (auto-generated — DO NOT EDIT)
export default "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover, user-scalable=no\">\n  <meta name=\"theme-color\" content=\"#0d0d10\">\n  <title>Aurora Mail</title>\n  <script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n  <style>\n    :root {\n      --bg: #0d0d10;\n      --surface: #16161c;\n      --surface-2: #1d1d26;\n      --surface-3: #25252f;\n      --line: #2a2a36;\n      --text: #f2f2f5;\n      --muted: #8e8e9c;\n      --faint: #5c5c6a;\n      --accent: #6c8cff;\n      --accent-2: #8d7cff;\n      --gold: #f5c453;\n      --green: #3ddc97;\n      --red: #ff6b7a;\n      --radius: 16px;\n      --safe-b: env(safe-area-inset-bottom, 0px);\n      --safe-t: env(safe-area-inset-top, 0px);\n    }\n    * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n    html, body { height: 100%; }\n    body {\n      background: var(--bg);\n      color: var(--text);\n      font-family: 'Vazirmatn', -apple-system, 'Segoe UI', Tahoma, sans-serif;\n      font-size: 15px;\n      overflow: hidden;\n      padding-top: var(--safe-t);\n    }\n    button { font-family: inherit; font-size: inherit; color: inherit; background: none; border: none; cursor: pointer; }\n    ::-webkit-scrollbar { width: 0; display: none; }\n\n    /* ---------- layout ---------- */\n    #app { height: 100%; display: flex; flex-direction: column; }\n    .screen { display: none; flex: 1; flex-direction: column; min-height: 0; }\n    .screen.active { display: flex; }\n\n    /* ---------- top bar ---------- */\n    .topbar {\n      display: flex; align-items: center; gap: 10px;\n      padding: 14px 16px 12px;\n      background: var(--bg);\n      position: sticky; top: 0; z-index: 20;\n      border-bottom: 1px solid var(--line);\n    }\n    .topbar .tb-title { font-weight: 700; font-size: 17px; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n    .tb-count { font-size: 12px; color: var(--muted); background: var(--surface-2); padding: 2px 8px; border-radius: 999px; }\n    .icon-btn {\n      width: 36px; height: 36px; border-radius: 12px;\n      display: flex; align-items: center; justify-content: center;\n      background: var(--surface-2); color: var(--muted); flex: none;\n      transition: transform .12s;\n    }\n    .icon-btn:active { transform: scale(0.92); background: var(--surface-3); }\n\n    /* ---------- list ---------- */\n    .scroll { flex: 1; overflow-y: auto; -webkit-overflow-scrolling: touch; padding: 12px 14px calc(20px + var(--safe-b)); }\n    .scroll.tight { padding-top: 4px; }\n\n    .card {\n      background: var(--surface);\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      padding: 13px 14px;\n      margin-bottom: 10px;\n      transition: transform .12s, background .15s;\n      display: block; width: 100%; text-align: right;\n    }\n    .card:active { transform: scale(0.985); background: var(--surface-2); }\n    .card.otp { border-color: rgba(245,196,83,.42); background: linear-gradient(180deg, rgba(245,196,83,.07), var(--surface) 60%); }\n\n    .row1 { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }\n    .avatar {\n      width: 34px; height: 34px; border-radius: 11px; flex: none;\n      display: flex; align-items: center; justify-content: center;\n      font-weight: 700; font-size: 14px; color: #fff;\n      background: var(--surface-3);\n    }\n    .who { flex: 1; min-width: 0; }\n    .sender { font-weight: 600; font-size: 14.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n    .subj { font-size: 13.5px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: 1px; }\n    .time { font-size: 11.5px; color: var(--faint); flex: none; padding-top: 2px; }\n    .preview { font-size: 13px; color: var(--muted); line-height: 1.55; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n    .otp-chip {\n      display: inline-flex; align-items: center; gap: 6px; margin-top: 8px;\n      background: rgba(245,196,83,.12); color: var(--gold);\n      border: 1px solid rgba(245,196,83,.3);\n      padding: 5px 11px; border-radius: 10px; font-weight: 700; font-size: 15px;\n      font-family: 'SF Mono', ui-monospace, monospace; letter-spacing: 1.5px; direction: ltr;\n    }\n\n    /* ---------- detail ---------- */\n    .mail-head { padding: 4px 16px 14px; border-bottom: 1px solid var(--line); }\n    .mail-head h2 { font-size: 18px; font-weight: 700; line-height: 1.4; margin-bottom: 8px; }\n    .meta { font-size: 12.5px; color: var(--muted); line-height: 1.7; }\n    .meta b { color: var(--text); font-weight: 600; }\n    .mail-body {\n      padding: 16px;\n      font-size: 14.5px; line-height: 1.75; color: var(--text);\n      white-space: pre-wrap; word-break: break-word; overflow-wrap: anywhere;\n    }\n    .mail-body a { color: var(--accent); text-decoration: none; border-bottom: 1px solid rgba(108,140,255,.4); }\n    .mail-body iframe { width: 100%; border: 0; border-radius: 12px; margin: 10px 0; background: #000; }\n    .mail-body img { max-width: 100%; border-radius: 12px; margin: 8px 0; }\n    .otp-big {\n      display: flex; align-items: center; justify-content: space-between; gap: 10px;\n      background: rgba(245,196,83,.1); border: 1px solid rgba(245,196,83,.32);\n      border-radius: 14px; padding: 12px 14px; margin: 0 16px 14px;\n    }\n    .otp-big code { font-size: 22px; font-weight: 700; color: var(--gold); letter-spacing: 3px; font-family: 'SF Mono', ui-monospace, monospace; direction: ltr; }\n    .copy-btn { background: rgba(245,196,83,.16); color: var(--gold); padding: 7px 14px; border-radius: 10px; font-weight: 600; font-size: 13px; }\n\n    /* ---------- addresses ---------- */\n    .addr-card { display: flex; align-items: center; gap: 11px; }\n    .addr-main { flex: 1; min-width: 0; }\n    .addr-mail { font-size: 14.5px; font-weight: 600; direction: ltr; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n    .addr-sub { font-size: 12px; color: var(--faint); margin-top: 2px; }\n    .addr-actions { display: flex; gap: 6px; flex: none; }\n    .mini-btn {\n      background: var(--surface-2); border: 1px solid var(--line); color: var(--muted);\n      padding: 6px 10px; border-radius: 9px; font-size: 12px; font-weight: 600;\n    }\n    .mini-btn:active { background: var(--surface-3); }\n    .mini-btn.danger { color: var(--red); border-color: rgba(255,107,122,.3); }\n    .badge-new { font-size: 10.5px; color: var(--green); background: rgba(61,220,151,.12); padding: 2px 7px; border-radius: 999px; font-weight: 700; }\n\n    /* ---------- empty / loading ---------- */\n    .empty { text-align: center; padding: 70px 30px; color: var(--muted); }\n    .empty .ico { font-size: 46px; margin-bottom: 14px; opacity: .8; }\n    .empty p { font-size: 14.5px; line-height: 1.7; }\n    .spin { width: 26px; height: 26px; border: 2.5px solid var(--surface-3); border-top-color: var(--accent); border-radius: 50%; animation: sp .7s linear infinite; margin: 44px auto; }\n    @keyframes sp { to { transform: rotate(360deg); } }\n\n    /* ---------- bottom bar ---------- */\n    .tabbar {\n      display: flex; gap: 4px;\n      padding: 8px 10px calc(8px + var(--safe-b));\n      background: var(--bg); border-top: 1px solid var(--line);\n      position: sticky; bottom: 0; z-index: 20;\n    }\n    .tab {\n      flex: 1; display: flex; flex-direction: column; align-items: center; gap: 3px;\n      padding: 7px 2px; border-radius: 12px; color: var(--faint); font-size: 11px; font-weight: 600;\n      transition: color .15s, background .15s;\n    }\n    .tab svg { width: 21px; height: 21px; }\n    .tab.on { color: var(--accent); background: rgba(108,140,255,.1); }\n\n    /* ---------- primary button ---------- */\n    .fab-fixed { padding: 0 16px calc(14px + var(--safe-b)); background: var(--bg); border-top: 1px solid var(--line); }\n    .btn-primary {\n      width: 100%; padding: 14px; border-radius: 14px; font-weight: 700; font-size: 15.5px;\n      background: linear-gradient(135deg, var(--accent), var(--accent-2)); color: #fff;\n      box-shadow: 0 6px 22px rgba(108,140,255,.28);\n      transition: transform .12s;\n    }\n    .btn-primary:active { transform: scale(0.98); }\n    .btn-ghost {\n      width: 100%; padding: 13px; border-radius: 14px; font-weight: 600; font-size: 15px;\n      background: var(--surface-2); color: var(--text); border: 1px solid var(--line);\n    }\n    .btn-ghost:active { transform: scale(0.98); background: var(--surface-3); }\n\n    /* ---------- toast ---------- */\n    #toast {\n      position: fixed; bottom: calc(86px + var(--safe-b)); left: 50%; transform: translateX(-50%) translateY(16px);\n      background: #f2f2f5; color: #0d0d10; padding: 10px 20px; border-radius: 999px;\n      font-size: 13.5px; font-weight: 600; z-index: 99; opacity: 0; pointer-events: none;\n      transition: opacity .2s, transform .2s; box-shadow: 0 8px 30px rgba(0,0,0,.45); max-width: 86vw; text-align: center;\n    }\n    #toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n\n    /* ---------- html mail ---------- */\n    .html-mail { border: 0; width: 100%; min-height: 200px; }\n\n    /* ---------- compose/new-address sheet ---------- */\n    .sheet-bg { position: fixed; inset: 0; background: rgba(0,0,0,.62); z-index: 60; opacity: 0; pointer-events: none; transition: opacity .2s; backdrop-filter: blur(3px); }\n    .sheet-bg.show { opacity: 1; pointer-events: auto; }\n    .sheet {\n      position: fixed; bottom: 0; left: 0; right: 0; z-index: 61;\n      background: var(--surface); border-radius: 22px 22px 0 0;\n      padding: 8px 18px calc(20px + var(--safe-b));\n      transform: translateY(102%); transition: transform .26s cubic-bezier(.32,.72,0,1);\n      max-height: 84vh; overflow-y: auto;\n    }\n    .sheet.show { transform: translateY(0); }\n    .sheet .grab { width: 38px; height: 4px; border-radius: 99px; background: var(--line); margin: 6px auto 16px; }\n    .sheet h3 { font-size: 17px; font-weight: 700; margin-bottom: 14px; }\n    .field {\n      width: 100%; padding: 13px 14px; border-radius: 13px;\n      background: var(--bg); border: 1px solid var(--line); color: var(--text);\n      font-family: inherit; font-size: 15px; outline: none; direction: ltr; text-align: left;\n    }\n    .field:focus { border-color: var(--accent); }\n    .field::placeholder { color: var(--faint); }\n    .domain-hint { font-size: 12.5px; color: var(--muted); margin: 9px 4px 14px; }\n    .sheet .btn-primary { margin-top: 4px; }\n\n    /* ---------- skeleton ---------- */\n    .skel { background: var(--surface-2); border-radius: 10px; animation: sk 1.3s ease-in-out infinite; }\n    @keyframes sk { 0%,100% { opacity: .5; } 50% { opacity: 1; } }\n    .skel-card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px; margin-bottom: 10px; }\n  </style>\n</head>\n<body>\n<div id=\"app\">\n\n  <!-- ============ INBOX ============ -->\n  <section class=\"screen active\" id=\"s-inbox\">\n    <div class=\"topbar\">\n      <div class=\"tb-title\" id=\"inbox-title\">📥 All Inbox</div>\n      <div class=\"tb-count\" id=\"inbox-count\"></div>\n      <button class=\"icon-btn\" id=\"btn-refresh\" title=\"Refresh\">⟳</button>\n    </div>\n    <div class=\"scroll tight\" id=\"inbox-list\"></div>\n    <div class=\"fab-fixed\">\n      <button class=\"btn-primary\" id=\"btn-new\">✏️ New Address</button>\n    </div>\n  </section>\n\n  <!-- ============ MAIL DETAIL ============ -->\n  <section class=\"screen\" id=\"s-mail\">\n    <div class=\"topbar\">\n      <button class=\"icon-btn\" id=\"mail-back\">›</button>\n      <div class=\"tb-title\">✉️ Mail</div>\n      <button class=\"icon-btn\" id=\"mail-copy\">⧉</button>\n    </div>\n    <div class=\"mail-head\" id=\"mail-head\"></div>\n    <div class=\"mail-body\" id=\"mail-body\"></div>\n  </section>\n\n  <!-- ============ ADDRESSES ============ -->\n  <section class=\"screen\" id=\"s-addr\">\n    <div class=\"topbar\">\n      <div class=\"tb-title\">📬 My Addresses</div>\n      <div class=\"tb-count\" id=\"addr-count\"></div>\n    </div>\n    <div class=\"scroll tight\" id=\"addr-list\"></div>\n    <div class=\"fab-fixed\">\n      <button class=\"btn-primary\" id=\"btn-new2\">✏️ New Address</button>\n    </div>\n  </section>\n\n  <!-- bottom tabs -->\n  <div class=\"tabbar\">\n    <button class=\"tab on\" data-s=\"s-inbox\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 12h-6l-2 3h-4l-2-3H2\"/><path d=\"M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z\"/></svg>\n      <span>Inbox</span>\n    </button>\n    <button class=\"tab\" data-s=\"s-addr\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 4h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z\"/><polyline points=\"22,6 12,13 2,6\"/></svg>\n      <span>Addresses</span>\n    </button>\n  </div>\n</div>\n\n<!-- new address sheet -->\n<div class=\"sheet-bg\" id=\"sheet-bg\"></div>\n<div class=\"sheet\" id=\"sheet\">\n  <div class=\"grab\"></div>\n  <h3>✏️ New Address</h3>\n  <input class=\"field\" id=\"sheet-name\" placeholder=\"Address name (optional)\" autocomplete=\"off\" spellcheck=\"false\">\n  <div class=\"domain-hint\">Final address: <b id=\"sheet-preview\"></b></div>\n  <button class=\"btn-primary\" id=\"sheet-create\">Create Address</button>\n  <div style=\"height:10px\"></div>\n  <button class=\"btn-ghost\" id=\"sheet-random\">🎲 Random</button>\n  <div style=\"height:8px\"></div>\n  <button class=\"btn-ghost\" id=\"sheet-close\">Cancel</button>\n</div>\n\n<div id=\"toast\"></div>\n\n<script>\n/* ============================================================\n   Aurora Mail — Telegram Mini App\n   همه‌ی داده‌ها از /mini API ورکر میاد. کلاینت فقط نمایش می‌ده.\n   ============================================================ */\nconst TG = window.Telegram && window.Telegram.WebApp;\nif (TG) {\n  TG.ready();\n  TG.expand();\n  if (TG.setHeaderColor) TG.setHeaderColor('#0d0d10');\n  if (TG.setBackgroundColor) TG.setBackgroundColor('#0d0d10');\n  if (TG.enableClosingConfirmation) TG.enableClosingConfirmation();\n}\nlet tgUser = (TG && TG.initDataUnsafe && TG.initDataUnsafe.user) || null;\n// fallback برای تست خارج تلگرام\nif (!tgUser) tgUser = { id: 1776112463, first_name: 'Rez' };\n\nconst $ = (s) => document.querySelector(s);\nconst $$ = (s) => [...document.querySelectorAll(s)];\nconst esc = (s) => String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst API = 'mini';\n\nlet state = {\n  addresses: [],\n  activeAddr: null,   // null = همه\n  mails: [],\n  openMailId: null,\n  loading: false,\n};\n\n/* ---------- helpers ---------- */\nfunction toast(msg) {\n  const t = $('#toast');\n  t.textContent = msg;\n  t.classList.add('show');\n  clearTimeout(toast._t);\n  toast._t = setTimeout(() => t.classList.remove('show'), 2200);\n}\n\nfunction avatarOf(sender) {\n  const s = String(sender || '?');\n  const name = s.replace(/^\"|\"$/g, '').split('<')[0].trim();\n  const initials = name.split(/[\\s@._-]+/).filter(Boolean).slice(0, 2).map(w => w[0].toUpperCase()).join('');\n  let h = 0;\n  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;\n  const hues = [222, 262, 158, 24, 340, 190, 40];\n  const hue = hues[h % hues.length];\n  return { initials: initials || '?', bg: `hsl(${hue} 62% 34%)` };\n}\n\nfunction fmtTime(ts) {\n  const d = new Date(ts * 1000);\n  const now = new Date();\n  const sameDay = d.toDateString() === now.toDateString();\n  const hm = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');\n  if (sameDay) return hm;\n  const days = Math.floor((now - d) / 86400000);\n  if (days < 7) return d.toLocaleDateString('en-GB', { weekday: 'short' });\n  return d.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });\n}\n\n// بدنه‌ی ایمیل رو قابل خواندن می‌کنه: URL‌ها لینک، خطوط جدید حفظ\nfunction renderBody(text) {\n  if (!text) return '<span style=\"color:var(--faint)\">(no content)</span>';\n  let t = esc(text);\n  // URL‌ها به لینک تبدیل (شامل mailto)\n  t = t.replace(/(https?:\\/\\/[^\\s<>\"']+)/g, (m) => {\n    const url = m.replace(/[).,;:!?]+$/, '');\n    return `<a href=\"${url}\" target=\"_blank\" rel=\"noopener\">${url.length > 60 ? url.slice(0, 57) + '…' : url}</a>`;\n  });\n  t = t.replace(/([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,})/g, '<a href=\"mailto:$1\">$1</a>');\n  return `<div class=\"plain-fallback\">${t}</div>`;\n}\n\nfunction extractOtp(body) {\n  if (!body) return null;\n  const b = body.replace(/\\s+/g, ' ');\n  const pats = [\n    /\\b(\\d{4,8})\\s*(?:is your|code|کد|رمز|one-time|one time|verification|verify|confirm)/i,\n    /(?:code is|کد|رمز|one-time code|otp)[:\\s=]*\\b(\\d{4,8})\\b/i,\n    /\\b(\\d{6})\\b(?=\\s*(?:is your|کد|رمز))/i,\n    /\\b(\\d{5})\\b/,\n  ];\n  for (const p of pats) {\n    const m = b.match(p);\n    if (m && m[1] && !/^0+$/.test(m[1])) return m[1];\n  }\n  return null;\n}\n\n/* ---------- API ---------- */\nasync function api(path, opts) {\n  const res = await fetch(API + path, {\n    method: opts && opts.method || 'GET',\n    headers: { 'Content-Type': 'application/json' },\n    body: opts && opts.body ? JSON.stringify(opts.body) : undefined,\n  });\n  if (!res.ok) {\n    let msg = 'Server error (' + res.status + ')';\n    try { const j = await res.json(); if (j && j.error) msg = j.error; } catch {}\n    throw new Error(msg);\n  }\n  return res.json();\n}\n\n/* ---------- screens ---------- */\nfunction show(id) {\n  $$('.screen').forEach(s => s.classList.remove('active'));\n  $('#' + id).classList.add('active');\n  $$('.tab').forEach(t => t.classList.toggle('on', t.dataset.s === id));\n  window.scrollTo(0, 0);\n}\n\n/* ---------- inbox ---------- */\nasync function loadInbox() {\n  const list = $('#inbox-list');\n  if (!state.mails.length) list.innerHTML = '<div class=\"spin\"></div>';\n  try {\n    const q = state.activeAddr ? '?addr=' + encodeURIComponent(state.activeAddr) : '';\n    const data = await api('/inbox' + q);\n    state.mails = data.mails || [];\n    state.activeAddr = data.active || null;\n    $('#inbox-title').textContent = state.activeAddr ? '📥 ' + state.activeAddr : '📥 All Inbox';\n    $('#inbox-count').textContent = state.mails.length ? state.mails.length : '';\n    renderInbox();\n  } catch (e) {\n    list.innerHTML = `<div class=\"empty\"><div class=\"ico\">⚠️</div><p>${esc(e.message)}</p></div>`;\n  }\n}\n\nfunction renderInbox() {\n  const list = $('#inbox-list');\n  if (!state.mails.length) {\n    list.innerHTML = `<div class=\"empty\">\n      <div class=\"ico\">📬</div>\n      <p>No emails yet.<br>Verification codes will show up here!</p>\n    </div>`;\n    return;\n  }\n  list.innerHTML = state.mails.map(m => {\n    const a = avatarOf(m.sender);\n    const otp = extractOtp(m.body);\n    const body1 = (m.body || '').replace(/\\n{2,}/g, '\\n').trim();\n    return `<button class=\"card${otp ? ' otp' : ''}\" data-id=\"${m.id}\">\n      <div class=\"row1\">\n        <div class=\"avatar\" style=\"background:${a.bg}\">${esc(a.initials)}</div>\n        <div class=\"who\">\n          <div class=\"sender\">${esc(m.sender || '?')}</div>\n          <div class=\"subj\">${esc(m.subject || '(no subject)')}</div>\n        </div>\n        <div class=\"time\">${fmtTime(m.received_at)}</div>\n      </div>\n      <div class=\"preview\">${esc(body1.slice(0, 180))}</div>\n      ${otp ? `<div class=\"otp-chip\">🔐 ${esc(otp)}</div>` : ''}\n    </button>`;\n  }).join('');\n  list.querySelectorAll('.card').forEach(c =>\n    c.addEventListener('click', () => openMail(c.dataset.id)));\n}\n\n/* ---------- mail detail ---------- */\nasync function openMail(id) {\n  state.openMailId = id;\n  show('s-mail');\n  $('#mail-head').innerHTML = '<div class=\"spin\"></div>';\n  $('#mail-body').innerHTML = '';\n  try {\n    const m = await api('/mail/' + id);\n    const a = avatarOf(m.sender);\n    const otp = extractOtp(m.body);\n    $('#mail-head').innerHTML = `\n      <h2>${esc(m.subject || '(no subject)')}</h2>\n      <div class=\"meta\">\n        <div style=\"display:flex;align-items:center;gap:9px;margin-bottom:6px\">\n          <div class=\"avatar\" style=\"background:${a.bg}\">${esc(a.initials)}</div>\n          <div><b>${esc(m.sender || '?')}</b><br><span style=\"color:var(--faint)\">${new Date(m.received_at * 1000).toLocaleString('en-GB')}</span></div>\n        </div>\n        <div>To <b dir=\"ltr\">${esc(m.address)}</b></div>\n      </div>`;\n    if (otp) {\n      $('#mail-body').innerHTML = `<div class=\"otp-big\"><code>${esc(otp)}</code>\n        <button class=\"copy-btn\" id=\"otp-copy\">Copy code</button></div>` + renderBody(m.body);\n      $('#otp-copy').addEventListener('click', () => copy(otp, 'Code copied'));\n    } else {\n      $('#mail-body').innerHTML = renderBody(m.body);\n    }\n    // اگه ایمیل لایه‌ی HTML داره، دقیقاً همون چیزی که فرستنده فرستاده\n    // رو داخل iframe سندباکس‌شده رندر کن — مثل یه کلاینت واقعی\n    maybeRenderHtml(m);\n  } catch (e) {\n    $('#mail-body').innerHTML = `<div class=\"empty\"><div class=\"ico\">⚠️</div><p>${esc(e.message)}</p></div>`;\n  }\n}\n\nfunction maybeRenderHtml(m) {\n  if (!m.html_snippet) return;\n  try {\n    const frame = document.createElement('iframe');\n    frame.className = 'html-mail';\n    frame.sandbox = 'allow-same-origin allow-popups';\n    // فقط ایمیل‌هایی که واقعاً HTML هستن (نه متن که ضمناً رندر شده)\n    if (m.html_snippet.trim().length < 30) return;\n    frame.srcdoc = `<!DOCTYPE html><html dir=\"ltr\"><head><meta charset=\"UTF-8\">\n      <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n      <style>\n        body{font-family:-apple-system,Segoe UI,Tahoma,sans-serif;font-size:14px;color:#111;background:#fff;margin:0;padding:12px}\n        img{max-width:100%!important;height:auto!important}\n        a{color:#2b6cb0;word-break:break-all}\n        table{max-width:100%!important}\n        div,td,th{max-width:100%!important}\n        *{box-sizing:border-box}\n      </style></head><body>${m.html_snippet}</body></html>`;\n    // متن plain رو پاک کن — HTML اصلی جاش رو می‌گیره\n    const body = $('#mail-body');\n    const plain = body.querySelector('.plain-fallback');\n    if (plain) plain.remove();\n    body.appendChild(frame);\n    // ارتفاع خودکار: بعد از load، بدون display:none اندازه بگیر\n    const resize = () => {\n      try {\n        const doc = frame.contentDocument;\n        if (!doc) return;\n        // جلوگیری از سرریز افقی: عرض کانتینر رو به iframe پاس بده\n        const w = body.clientWidth;\n        if (w > 0) frame.style.width = w + 'px';\n        const h = Math.max(doc.documentElement.scrollHeight, doc.body ? doc.body.scrollHeight : 0);\n        frame.style.height = Math.min(Math.max(h + 16, 100), 3200) + 'px';\n      } catch {}\n    };\n    frame.addEventListener('load', () => {\n      resize();\n      // بعضی ایمیل‌ها کُند لود می‌شن — دوباره بعد از یه لحظه\n      setTimeout(resize, 300);\n      setTimeout(resize, 900);\n    });\n  } catch {}\n}\n\n/* ---------- addresses ---------- */\nasync function loadAddresses() {\n  const list = $('#addr-list');\n  list.innerHTML = '<div class=\"spin\"></div>';\n  try {\n    const data = await api('/addresses');\n    state.addresses = data.addresses || [];\n    $('#addr-count').textContent = state.addresses.length || '';\n    renderAddresses();\n  } catch (e) {\n    list.innerHTML = `<div class=\"empty\"><div class=\"ico\">⚠️</div><p>${esc(e.message)}</p></div>`;\n  }\n}\n\nfunction renderAddresses() {\n  const list = $('#addr-list');\n  if (!state.addresses.length) {\n    list.innerHTML = `<div class=\"empty\"><div class=\"ico\">📭</div><p>No address created yet.<br>Use the button below to make one!</p></div>`;\n    return;\n  }\n  const unread = new Set((state.mails || []).map(m => m.id));\n  list.innerHTML = state.addresses.map(a => {\n    const isNew = a.last_mail_at && a.last_seen < a.last_mail_at;\n    return `<div class=\"card addr-card\">\n      <div class=\"addr-main\">\n        <div class=\"addr-mail\">${esc(a.address)}</div>\n        <div class=\"addr-sub\">${a.label ? esc(a.label) + ' · ' : ''}${fmtTime(a.last_used || a.created_at)}${a.mail_count != null ? ' · ' + a.mail_count + ' mails' : ''}</div>\n      </div>\n      ${isNew ? '<span class=\"badge-new\">NEW</span>' : ''}\n      <div class=\"addr-actions\">\n        <button class=\"mini-btn\" data-open=\"${esc(a.address)}\">Inbox</button>\n        <button class=\"mini-btn danger\" data-del=\"${a.id}\">Delete</button>\n      </div>\n    </div>`;\n  }).join('');\n  list.querySelectorAll('[data-open]').forEach(b =>\n    b.addEventListener('click', () => {\n      state.activeAddr = b.dataset.open;\n      show('s-inbox');\n      loadInbox();\n    }));\n  list.querySelectorAll('[data-del]').forEach(b =>\n    b.addEventListener('click', async () => {\n      if (!confirm('Delete this address and all its emails?')) return;\n      try {\n        await api('/address/' + b.dataset.del, { method: 'DELETE' });\n        toast('Deleted');\n        loadAddresses();\n        if (state.activeAddr) { state.activeAddr = null; loadInbox(); }\n      } catch (e) { toast(e.message); }\n    }));\n}\n\n/* ---------- copy ---------- */\nfunction copy(text, msg) {\n  const done = () => { toast(msg || 'Copied'); if (TG && TG.HapticFeedback) TG.HapticFeedback.impactOccurred('light'); };\n  if (TG && TG.clipboard && TG.clipboard.readText === undefined && TG.clipboard.writeText) {\n    TG.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text, done));\n  } else fallbackCopy(text, done);\n}\nfunction fallbackCopy(text, done) {\n  const ta = document.createElement('textarea');\n  ta.value = text;\n  ta.style.position = 'fixed';\n  ta.style.opacity = '0';\n  document.body.appendChild(ta);\n  ta.select();\n  try { document.execCommand('copy'); } catch {}\n  ta.remove();\n  done();\n}\n\n/* ---------- sheet ---------- */\nfunction openSheet() {\n  $('#sheet-bg').classList.add('show');\n  $('#sheet').classList.add('show');\n  updatePreview();\n  setTimeout(() => $('#sheet-name').focus(), 260);\n}\nfunction closeSheet() {\n  $('#sheet-bg').classList.remove('show');\n  $('#sheet').classList.remove('show');\n  $('#sheet-name').value = '';\n}\nfunction updatePreview() {\n  const name = ($('#sheet-name').value || '').trim().toLowerCase().replace(/[^a-z0-9._-]/g, '');\n  $('#sheet-preview').textContent = (name || 'random') + '@' + (window.__DOMAIN || 'mesterio.life');\n}\nasync function createAddress(random) {\n  const btn = $('#sheet-create');\n  btn.disabled = true;\n  btn.textContent = 'Creating…';\n  try {\n    const name = random ? null : ($('#sheet-name').value || '').trim();\n    const data = await api('/address', { method: 'POST', body: { name } });\n    toast('Address created ✅');\n    closeSheet();\n    await loadAddresses();\n    if (data && data.address) {\n      state.activeAddr = data.address;\n      show('s-inbox');\n      loadInbox();\n    }\n  } catch (e) {\n    toast(e.message);\n  } finally {\n    btn.disabled = false;\n    btn.textContent = 'Create Address';\n  }\n}\n\n/* ---------- events ---------- */\n$('#btn-refresh').addEventListener('click', () => {\n  if (TG && TG.HapticFeedback) TG.HapticFeedback.impactOccurred('light');\n  loadInbox();\n});\n$('#btn-new').addEventListener('click', openSheet);\n$('#btn-new2').addEventListener('click', openSheet);\n$('#sheet-close').addEventListener('click', closeSheet);\n$('#sheet-bg').addEventListener('click', closeSheet);\n$('#sheet-random').addEventListener('click', () => createAddress(true));\n$('#sheet-create').addEventListener('click', () => createAddress(false));\n$('#sheet-name').addEventListener('input', updatePreview);\n$('#mail-back').addEventListener('click', () => { show('s-inbox'); state.openMailId = null; });\n$('#mail-copy').addEventListener('click', () => {\n  const m = state.mails.find(x => String(x.id) === String(state.openMailId));\n  if (m) copy(m.body || '', 'Email text copied');\n});\n$$('.tab').forEach(t => t.addEventListener('click', () => {\n  const s = t.dataset.s;\n  show(s);\n  if (s === 's-addr') loadAddresses();\n  if (s === 's-inbox') loadInbox();\n}));\n\n/* ---------- boot ---------- */\n(async function boot() {\n  // domain رو از سرور بگیر\n  try {\n    const meta = await api('/meta');\n    window.__DOMAIN = meta.domain || 'mesterio.life';\n  } catch {}\n  updatePreview();\n  await loadInbox();\n})();\n</script>\n</body>\n</html>\n";
